/**
 * generated by stackra gen from the `offline` option of the consumed manifests' actions,
 * src/routes/offline/offline.route.ts (`prerender: true`) and src/config/i18n.config.ts (locales,
 * prefixes) — do not edit
 * Purpose: what the console can do without a network. `Offline` is the offline map: for each
 *          consumed action that declared `offline`, what the mutation queue of @stackra/query may
 *          do while the client is offline; every other action is online-only and refuses with
 *          `offline` at once. `offlinePages` lists the offline page gen renders per locale at build
 *          time, which the service worker precaches and serves when even the app shell is missing.
 * Boundary: a queued call keeps its Idempotency-Key and precondition; `onConflict` lists the
 *           resolutions the pending-changes view may offer for a 409. A destructive action at L3
 *           or above can never queue. The worker inlines the same page list (it imports nothing
 *           from the app), and gen checks both lists agree.
 * Runtime: browser
 */
import { ConflictResolution, IdMinting, OfflineMode, OfflinePrecondition } from "@stackra/actions";
import { offlineMap } from "@stackra/query";
import { ArchiveProductAction, CreateOrderAction } from "#stackra/clients/commerce";

/** Action → offline policy, exactly as each producer's manifest declares it. */
export const Offline = offlineMap([
  {
    action: CreateOrderAction,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Client,
    precondition: OfflinePrecondition.None,
    retention: "72h",
    onConflict: [ConflictResolution.ServerWins, ConflictResolution.Manual],
  },
  {
    action: ArchiveProductAction,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Server,
    precondition: OfflinePrecondition.Version,
    retention: "24h",
    onConflict: [
      ConflictResolution.ServerWins,
      ConflictResolution.ClientRetry,
      ConflictResolution.Manual,
    ],
  },
]);

/**
 * Locale → the prerendered offline page and the prefix that selects it; the worker answers a
 * navigation under a prefix with that locale's page, anything else with the default's.
 */
export const offlinePages = {
  en: { prefix: "", page: "/offline" },
  "en-US": { prefix: "/en-us", page: "/en-us/offline" },
  ar: { prefix: "/ar", page: "/ar/offline" },
  "ar-SA": { prefix: "/ar-sa", page: "/ar-sa/offline" },
} as const;
